import java.io.*;
import java.util.Arrays;

public class Main {
    // Monotonic stack of open intervals: strictly increasing heights, equal heights merged.
    // int fields: heights fit int32, widths and costs never exceed n
    static int[] height = new int[1 << 16];
    static int[] width = new int[1 << 16];
    static int[] cost = new int[1 << 16];
    static int top = 0; // index of the top node; node 0 is the height-0 sentinel

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        long n = readLong(in);
        for (long i = 0; i < n; i++) append((int) readLong(in), 1);
        append(0, 0); // virtual zero boundary closes every remaining interval
        System.out.println(cost[0]);
    }

    static void append(int h, int w) {
        int c = 0;
        while (height[top] > h) {
            int nh = height[top], nw = width[top], nc = cost[top];
            top--;
            int base = Math.max(h, height[top]);
            int value = (int) Math.min(nw, (long) nc + nh - base);
            if (height[top] >= h) {
                width[top] += nw;
                cost[top] += value;
            } else {
                w += nw;
                c += value;
            }
        }
        if (height[top] == h) {
            width[top] += w;
            cost[top] += c;
        } else {
            top++;
            if (top == height.length) {
                int size = height.length + (height.length >> 1); // 1.5x keeps peak memory low
                height = Arrays.copyOf(height, size);
                width = Arrays.copyOf(width, size);
                cost = Arrays.copyOf(cost, size);
            }
            height[top] = h;
            width[top] = w;
            cost[top] = c;
        }
    }

    private static long readLong(DataInputStream in) throws IOException {
        int c = in.read();
        while (c != -1 && c <= ' ') c = in.read();
        long x = 0;
        while (c > ' ') {
            x = x * 10 + (c - '0');
            c = in.read();
        }
        return x;
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

// 12-byte node: heights fit uint32, widths and costs never exceed n
type node struct{ height, width, cost uint32 }

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	readInt := func() int64 {
		c, err := reader.ReadByte()
		for err == nil && c <= ' ' {
			c, err = reader.ReadByte()
		}
		var x int64
		for err == nil && c > ' ' {
			x = x*10 + int64(c-'0')
			c, err = reader.ReadByte()
		}
		return x
	}
	// Monotonic stack of open intervals: strictly increasing heights, equal heights merged.
	st := []node{{0, 0, 0}}
	add := func(h, w uint32) {
		var c uint32
		for st[len(st)-1].height > h {
			nd := st[len(st)-1]
			st = st[:len(st)-1]
			t := &st[len(st)-1]
			base := max(h, t.height)
			value := uint32(min(uint64(nd.width), uint64(nd.cost)+uint64(nd.height)-uint64(base)))
			if t.height >= h {
				t.width += nd.width
				t.cost += value
			} else {
				w += nd.width
				c += value
			}
		}
		if t := &st[len(st)-1]; t.height == h {
			t.width += w
			t.cost += c
		} else {
			st = append(st, node{h, w, c})
		}
	}
	n := readInt()
	for i := int64(0); i < n; i++ {
		add(uint32(readInt()), 1)
	}
	add(0, 0) // virtual zero boundary closes every remaining interval
	fmt.Println(st[0].cost)
}
